from pathlib import Path
import sqlite3


def check_source_data_present(ws):
    root = Path(ws).parent / "system"
    dealcloud = root / "dealcloud_disposition_workspace" / "state.db"
    sharepoint = root / "sharepoint_tax_governance_library" / "state.db"
    if not dealcloud.exists() or not sharepoint.exists():
        return {"score": 0, "detail": "Required DealCloud or SharePoint state database is missing"}
    with sqlite3.connect(dealcloud) as connection:
        transaction = connection.execute(
            "SELECT structure_code, transaction_status FROM disposition_transactions "
            "WHERE transaction_id = ? AND case_id = ?",
            ("DC-TXN-25Q3-024", "CASE-FAIRFAX3-2025Q3"),
        ).fetchone()
        requirements = connection.execute(
            "SELECT COUNT(*) FROM closing_requirements "
            "WHERE transaction_id = ? AND active_flag = 1",
            ("DC-TXN-25Q3-024",),
        ).fetchone()[0]
    with sqlite3.connect(sharepoint) as connection:
        decision = connection.execute(
            "SELECT status, decision_code FROM decision_records "
            "WHERE decision_id = ? AND case_id = ?",
            ("DEC-2025-017", "CASE-FAIRFAX3-2025Q3"),
        ).fetchone()
    if transaction != ("installment_sale", "recommended"):
        return {"score": 0, "detail": f"Recommended transaction anchor is incorrect: {transaction}"}
    if requirements != 7:
        return {"score": 0, "detail": f"Expected 7 active recommended requirements, found {requirements}"}
    if decision != ("approved", "INSTALLMENT_ASSET_SALE"):
        return {"score": 0, "detail": f"Approved decision anchor is incorrect: {decision}"}
    return {"score": 1, "detail": "Recommended installment transaction, seven active requirements, and approved decision are present"}
